    "kayo:E": { en: "knife", how: "SIFIR/Noktası'nı kuşan ve sol tıkla fırlat. Bıçak ilk değdiği yüzeye saplanır; kısa süre sonra menzildeki rakipleri sindirir ve yerlerini gösterir." },
    "kayo:C": { en: "molly", how: "PARÇA/Tesirli'yi kuşan; sol tıkla at, sağ tıkla yavaş at. Yere indiğinde art arda dalgalarla hasar verir." },
    "gekko:C": { en: "mosh pit", how: "Pofu'yu kuşan; sol tıkla at, sağ tıkla yavaş at. İndiği yerde önce düşük hasar verir, sonra büyük bir patlamayla yüksek hasar verir." },
    "sage:C": { en: "wall", how: "Bariyer Küresi'ni kuşan. Yönünü tekrar etkinleştirerek çevir ya da sağ tıkı basılı tutup döndür, sol tıkla yerleştir. Duvar bir süre sonra güçlenir." },
