    "omen:E": { en: "smoke", how: "Karanlık Örtü'yü kuşan; haritadan değil, bakış yönünden nişan alırsın. Sağ tıkla mesafeyi ayarla, sol tıkla gönder; kürenin düştüğü yerde duman açılır." },
